CREATE TABLE companies (id SERIAL PRIMARY KEY,name TEXT NOT NULL,short_code TEXT NOT NULL UNIQUE,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
