ALTER TABLE stock_ledger ENABLE TRIGGER ALL;
CREATE TRIGGER stock_ledger_immutable BEFORE UPDATE OR DELETE ON stock_ledger FOR EACH ROW EXECUTE FUNCTION reject_ledger_mutation();
ALTER TABLE users ADD COLUMN language TEXT NOT NULL DEFAULT 'en', ADD COLUMN theme TEXT NOT NULL DEFAULT 'system', ADD COLUMN font_scale INTEGER NOT NULL DEFAULT 100;
ALTER TABLE users ADD CONSTRAINT user_preferences_valid CHECK(language IN ('en','hi','ta','te','ml','kn') AND theme IN ('light','dark','system') AND font_scale BETWEEN 90 AND 130);
UPDATE users SET token_version=token_version+1;
CREATE TABLE invites(id SERIAL PRIMARY KEY,tenant_id INTEGER NOT NULL REFERENCES companies(id),code_hash TEXT NOT NULL UNIQUE,email TEXT,role "Role" NOT NULL DEFAULT 'staff',expires_at TIMESTAMP(3) NOT NULL,used BOOLEAN NOT NULL DEFAULT false,created_by INTEGER NOT NULL,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
