CREATE TABLE audit_logs(id SERIAL PRIMARY KEY,tenant_id INTEGER NOT NULL REFERENCES companies(id),user_id INTEGER,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,before JSONB,after JSONB,ip_address TEXT,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
